CREATE TABLE "PBM_BUSINESS_RULES"."NETWORK_EXCLUSION_ASSC"
(
	"NETWORK_EXCLUSION_ASSC_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL,
	"NETWORK_ID" NUMBER NOT NULL,
	"EXCLUSION_ID" NUMBER NOT NULL,
    "IS_ENABLED" CHAR(1) DEFAULT '1',
    "LAST_UPDATE_DATE" DATE NOT NULL,
	CONSTRAINT PK_NetworkID_Assc_Exc PRIMARY KEY ("NETWORK_EXCLUSION_ASSC_ID"),
	CONSTRAINT UK_Network_Exc UNIQUE ("NETWORK_ID","EXCLUSION_ID"),
	CONSTRAINT FK_Network_Id_Exc FOREIGN KEY ("NETWORK_ID") REFERENCES "PBM_BUSINESS_RULES"."PROVIDER_NETWORK" ("NETWORK_ID"),
	CONSTRAINT FK_Exclusion_Id_Exc FOREIGN KEY ("EXCLUSION_ID") REFERENCES "PBM_BUSINESS_RULES"."DRUG_EXCLUSION_METADATA" ("EXCLUSION_ID")
);